import { spawn } from 'node:child_process';
import { writeFileSync } from 'node:fs';
import { setTimeout as sleep } from 'node:timers/promises';

const TARGET = process.argv[2];
const OUT = process.argv[3];
const PORT = 9345;
const PROFILE = process.argv[4];
const CHROME = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';

const chrome = spawn(CHROME, [
  '--headless=new', '--disable-gpu', '--no-first-run', '--no-default-browser-check',
  '--hide-scrollbars', '--window-size=1280,1400',
  '--host-resolver-rules=MAP * ~NOTFOUND',   // blackhole every network host: proves zero external runtime deps
  `--user-data-dir=${PROFILE}`, `--remote-debugging-port=${PORT}`, 'about:blank',
], { stdio: 'ignore' });

let version = null;
for (let i = 0; i < 60; i++) {
  try { version = await (await fetch(`http://127.0.0.1:${PORT}/json/version`)).json(); break; }
  catch { await sleep(250); }
}
if (!version) { chrome.kill(); throw new Error('chrome devtools not reachable'); }

const ws = new WebSocket(version.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
let id = 0;
const pending = new Map();
const events = [];
ws.onmessage = (m) => {
  const msg = JSON.parse(m.data);
  if (msg.id && pending.has(msg.id)) { const p = pending.get(msg.id); pending.delete(msg.id); msg.error ? p.rej(new Error(JSON.stringify(msg.error))) : p.res(msg.result); }
  else if (msg.method) events.push(msg);
};
const send = (method, params = {}, sessionId) => new Promise((res, rej) => {
  const mid = ++id; pending.set(mid, { res, rej });
  ws.send(JSON.stringify({ id: mid, method, params, ...(sessionId ? { sessionId } : {}) }));
});

const { targetId } = await send('Target.createTarget', { url: 'about:blank' });
const { sessionId } = await send('Target.attachToTarget', { targetId, flatten: true });
await send('Page.enable', {}, sessionId);
await send('Network.enable', {}, sessionId);
await send('Runtime.enable', {}, sessionId);
await send('Log.enable', {}, sessionId);
await send('Page.navigate', { url: TARGET }, sessionId);
for (let i = 0; i < 80; i++) { if (events.some(e => e.method === 'Page.loadEventFired')) break; await sleep(100); }
await sleep(600);

const requests = events.filter(e => e.method === 'Network.requestWillBeSent').map(e => e.params.request.url);
const failures = events.filter(e => e.method === 'Network.loadingFailed').map(e => e.params.errorText);
const consoleErrors = events.filter(e => e.method === 'Log.entryAdded' && e.params.entry.level === 'error').map(e => e.params.entry.text);
const exceptions = events.filter(e => e.method === 'Runtime.exceptionThrown').map(e => e.params.exceptionDetails.text);

const evaluate = async (expr) => {
  const r = await send('Runtime.evaluate', { expression: expr, returnByValue: true, awaitPromise: true }, sessionId);
  if (r.exceptionDetails) throw new Error(JSON.stringify(r.exceptionDetails));
  return r.result.value;
};

const probe = await evaluate(`(() => {
  const svg = document.querySelector('svg');
  const box = svg ? svg.getBoundingClientRect() : null;
  const nodes = [...document.querySelectorAll('.node')];
  const feature = document.querySelector('[data-id="LT-FEATURE-001"]');
  const fRect = feature ? feature.getBoundingClientRect() : null;
  const visible = (el) => { const r = el.getBoundingClientRect(); const s = getComputedStyle(el); return r.width > 0 && r.height > 0 && s.display !== 'none' && s.visibility !== 'hidden'; };
  return {
    svg_exists: !!svg,
    svg_width: box ? Math.round(box.width) : 0,
    svg_height: box ? Math.round(box.height) : 0,
    edge_paths: svg ? svg.querySelectorAll('path').length : 0,
    node_count: nodes.length,
    visible_node_count: nodes.filter(visible).length,
    feature_visible: feature ? visible(feature) : false,
    feature_text: feature ? feature.textContent.trim() : null,
    feature_size: fRect ? [Math.round(fRect.width), Math.round(fRect.height)] : null,
    task_texts: nodes.filter(n => n.dataset.id.startsWith('SYS-')).map(n => n.textContent.trim()),
    styles_applied: getComputedStyle(document.body).backgroundColor,
    graph_data_len: (document.querySelector('#graph-data') || {}).textContent?.length || 0,
    external_elements: [...document.querySelectorAll('script[src], link[href], img, iframe, object, embed, [style*="url("]')].length,
  };
})()`);

// prove the inline JS is live (no external runtime): type into the filter and observe DOM reaction
const jsAlive = await evaluate(`(() => {
  const q = document.querySelector('#q');
  q.value = 'SYS-LTF001-P07';
  q.dispatchEvent(new Event('input', { bubbles: true }));
  const hidden = [...document.querySelectorAll('.node.hidden')].length;
  const shown = [...document.querySelectorAll('.node:not(.hidden)')].map(n => n.dataset.id);
  q.value = '';
  q.dispatchEvent(new Event('input', { bubbles: true }));
  const restored = [...document.querySelectorAll('.node:not(.hidden)')].length;
  return { hidden_after_filter: hidden, shown_after_filter: shown, restored_after_clear: restored };
})()`);

const shot = await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: true }, sessionId);
writeFileSync(OUT, Buffer.from(shot.data, 'base64'));

console.log(JSON.stringify({ requests, failures, consoleErrors, exceptions, probe, jsAlive, screenshot: OUT }, null, 2));
ws.close(); chrome.kill();
process.exit(0);
